def f(g):
    h=len(g); w=len(g[0])
    n0=sum(1 for r in g for v in r if v==0)
    cnt={v:(h*w-n0)+r.count(v) if False else 0 for v in set(x for r in g for x in r)}
    tot=[g[r][c] for r in range(h) for c in range(w)]
    from collections import Counter
    cc=Counter(tot)
    # candidate fills
    best=None
    def bal(cells):
        ca=Counter(cells)
        return max(ca.values())-min(ca.values(), default=0)
    for v in set(cc):
        cells=[x for x in tot if x!=0]+[v]*n0
        bs=bal(cells)
        if best is None or bs<best[0]: best=(bs,bal(sum(cc)) , v)
    return [[v if x==0 else x for x in r] for r in g]
